{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C01"],
      "claim": "In humans, phytoene, a C40 polyisoprenoid hydrocarbon, was estimated by compartmental modeling to have 58.5 ± 18.9% absorption; this high value is only weakly transferable to the query because the query is a larger polyprenyl quinone with a polar redox-active head and different absorption/efflux characteristics.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C02"],
      "claim": "Mulberroside A showed low oral bioavailability in humans after rapid intestinal deglycosylation; although structurally dissimilar to the query, it provides affirmative low-bioavailability evidence, but with low transferability.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted low: the query is ubiquinone-9, a high-molecular-weight polyprenyl quinone with very poor aqueous solubility and known low oral bioavailability. The high phytoene absorption values are weakly transferable because phytoene is a smaller nonpolar hydrocarbon; the low mulberroside A result is also weakly transferable but directionally consistent. Overall, evidence does not support F >= 20%.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for ubiquinone-9 in the provided evidence.",
    "The closest high-bioavailability analogue (phytoene) is a hydrocarbon carotenoid, not a quinone, and its compartmental-model estimate may not reflect true absolute F.",
    "The low-bioavailability analogue (mulberroside A) is a glycoside with a different absorption-limiting mechanism."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

